/**
 * Transcript value objects. Times are in SECONDS (floats) throughout the
 * domain; YouTube's millisecond fields are converted at the parser boundary.
 */

export type Segment = {
  start: number
  dur: number
  text: string
}

/** Which capture strategy produced the transcript. */
export type TranscriptSource = 'intercept' | 'dom' | 'manual'

export type Transcript = {
  videoId: string
  /** BCP-47-ish code as YouTube reports it ("en", "ru", "en-US"), or "und". */
  lang: string
  /** True for auto-generated (ASR) captions — noisier, no punctuation. */
  autoGenerated: boolean
  /**
   * False when the text came without timestamps (manual paste of plain text).
   * Every segment then has start 0 and the map gets no seek targets.
   */
  timed: boolean
  source: TranscriptSource
  segments: Segment[]
}

export type Chapter = { title: string; start: number }

export type CaptionTrack = {
  languageCode: string
  name: string
  autoGenerated: boolean
}

export type VideoMeta = {
  videoId: string
  title: string
  channel: string
  durationSec: number
  chapters: Chapter[]
  captionTracks: CaptionTrack[]
}

/** A line of transcript text with its start time, ready for the LLM. */
export type TimedLine = { start: number; text: string }

export function isUsableTranscript(t: Transcript | null | undefined): t is Transcript {
  return !!t && t.segments.some((s) => s.text.trim().length > 0)
}
